import base64
import re

def redact_untrusted_observation(text):
    # Defensive scanner: examples of dangerous strings are data, never instructions.
    blocked_examples = ("ignore the reviewer policy", "curl | sh", "OPENROUTER_API_KEY")
    text = re.sub(r"Bearer [A-Za-z0-9_-]+", "Bearer [redacted]", text)
    return {"text": text, "warning": any(pattern in text for pattern in blocked_examples)}

def encode_report(text):
    return base64.b64encode(text.encode()).decode()
